INSERT INTO roles (id, tenant_id, key, label, description, system, priority, created_at, updated_at) SELECT RANDOM_UUID(), NULL, k.key, k.label, k.label, TRUE, k.priority, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM (VALUES ('ADMIN', 'Administrateur', 950), ('CAMPUS_ADMIN', 'Administrateur Campus', 690), ('CHEF_DE_FAMILLE', 'Chef de famille', 300), ('CHURCH_ADMIN', 'Admin Eglise', 700), ('DEPARTMENT_ADMIN', 'Admin Departement', 500), ('DEPARTMENT_LEADER', 'Leader Departement', 400), ('FAISEUR', 'Faiseur de disciples', 200), ('FAMILY_LEADER', 'Chef de Famille', 300), ('HEALTH_LEAD', 'Responsable Sante', 300), ('HEALTH_STAFF', 'Personnel Sante', 250), ('MEMBRE', 'Membre', 100), ('PASTEUR', 'Pasteur', 850), ('PASTOR_PRINCIPAL', 'Pasteur Principal', 860), ('REGION_ADMIN', 'Administrateur Region', 750), ('RESPONSABLE', 'Responsable de département', 400), ('SUB_CHURCH_ADMIN', 'Administrateur Sous-Eglise', 680), ('TENANT_ADMIN', 'Admin Tenant', 800), ('TENANT_OWNER', 'Proprietaire Tenant', 900)) AS k(key, label, priority) WHERE NOT EXISTS (SELECT 1 FROM roles ro WHERE ro.tenant_id IS NULL AND ro.key = k.key);

